import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.StringJoiner;

public class OrderRequest {
    private final String baseUri;
    private final String path;
    private final Map<String, String> query;

    private OrderRequest(String baseUri, String path, Map<String, String> query) {
        this.baseUri = baseUri;
        this.path = path;
        this.query = query;
    }

    public static Builder builder() { return new Builder(); }

    public String url() {
        StringBuilder sb = new StringBuilder(baseUri).append(path);
        if (!query.isEmpty()) {
            StringJoiner j = new StringJoiner("&", "?", "");
            query.forEach((k, v) -> j.add(k + "=" + URLEncoder.encode(v, StandardCharsets.UTF_8)));
            sb.append(j);
        }
        return sb.toString();
    }

    public static class Builder {
        private String baseUri;
        private String path = "";
        private final Map<String, String> query = new LinkedHashMap<>();

        public Builder baseUri(String b) { this.baseUri = b; return this; }
        public Builder path(String p) { this.path = p; return this; }
        public Builder query(String k, String v) { query.put(k, v); return this; }

        public OrderRequest build() {
            if (baseUri == null) throw new IllegalStateException("baseUri is required");
            return new OrderRequest(baseUri, path, new LinkedHashMap<>(query));
        }
    }
}

