import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class OrderRequestTest {
    @Test
    void buildsUrlWithEncodedQuery() {
        String url = OrderRequest.builder().baseUri("https://api.test").path("/orders")
            .query("status", "open").query("q", "a b").build().url();
        assertEquals("https://api.test/orders?status=open&q=a+b", url);
    }

    @Test
    void noQueryMeansNoQuestionMark() {
        assertEquals("https://api.test/orders", OrderRequest.builder().baseUri("https://api.test").path("/orders").build().url());
    }

    @Test
    void missingBaseUriFails() {
        assertThrows(IllegalStateException.class, () -> OrderRequest.builder().path("/x").build());
    }
}
